}

declare global {
    interface Window {
        md2Actions?: ElectronActionBridge
    }
}

let actionBridgeOverride: ElectronActionBridge | null = null

export function setActionBridgeOverride(bridge: ElectronActionBridge | null) {
    actionBridgeOverride = bridge
}

export function getElectronActionBridge() {
    if (actionBridgeOverride) return actionBridgeOverride

    return window.md2Actions ?? null
}

export function hasActionRunBackend() {
    return getElectronActionBridge() !== null
}

interface ActionScheduleSnapshot {
    message: string | null
    open: boolean
    timestamp: string
}

type Listener = () => void

const INITIAL_SNAPSHOT: ActionScheduleSnapshot = { message: null, open: false, timestamp: '' }

/** Owns schedule form state at schedule-section boundary. */
export class ActionScheduleStore {
    private readonly listeners = new Set<Listener>()
    private snapshot = INITIAL_SNAPSHOT

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    toggle() {
        this.publish({ ...this.snapshot, message: null, open: !this.snapshot.open })
    }

    setTimestamp(timestamp: string) {
        this.publish({ ...this.snapshot, message: null, timestamp })
    }

    setMessage(message: string | null) {
        this.publish({ ...this.snapshot, message })
    }

    private publish(snapshot: ActionScheduleSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { useSyncExternalStore, type ChangeEvent } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { defaultScheduleAction } from '../popup/action_popup_defaults'
import type { ActionScheduleStore } from './action_schedule_store'
import { ActionScheduleForm } from './action_schedule_form'
import { createScheduleTrigger } from './action_schedule_trigger'

interface ActionScheduleOwnerProps {
    action: ActionDefinition
    context: ActionContext
    store: ActionScheduleStore
}

/** Owns schedule form state and registration. */
export function ActionScheduleOwner({ action, context, store }: ActionScheduleOwnerProps) {
    const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    if (!snapshot.open) return null

    const handleTimestampChange = (event: ChangeEvent<HTMLInputElement>) => store.setTimestamp(event.target.value)
    const handleRegister = async () => {
        store.setMessage(null)
        try {
            const trigger = createScheduleTrigger(store.getSnapshot().timestamp)
            await defaultScheduleAction(action, context, trigger)
            store.setMessage('Schedule registered')
        } catch (error) {
            store.setMessage(error instanceof Error ? error.message : 'Could not register schedule')
        }
    }

    return (
        <ActionScheduleForm
            message={snapshot.message}
            onRegister={handleRegister}
            onTimestampChange={handleTimestampChange}
            timestamp={snapshot.timestamp}
        />
    )
}

import type { ActionScheduleTrigger } from '../../../../data/action_schedule_types'

/** Validate a local date/time input and create its absolute scheduler timestamp. */
export function createScheduleTrigger(timestampInput: string, now = Date.now()): ActionScheduleTrigger {
    const timestamp = timestampInput.trim()
    if (timestamp.length === 0) throw new Error('Timestamp is required for time schedules')
    const fireAt = Date.parse(timestamp)
    if (Number.isNaN(fireAt)) throw new Error('Schedule timestamp is invalid')
    if (fireAt <= now) throw new Error('Schedule time must be in the future')

    return { timestamp: new Date(fireAt).toISOString(), type: 'at' }
}

import { Button, Stack, TextField, Typography } from '@mui/material'
import type { ChangeEvent } from 'react'

interface ActionScheduleFormProps {
    message: string | null
    onRegister: () => void
    onTimestampChange: (event: ChangeEvent<HTMLInputElement>) => void
    timestamp: string
}

/** Presentation-only scheduled action registration form. */
export function ActionScheduleForm(props: ActionScheduleFormProps) {
    const {
        message,
        onRegister,
        onTimestampChange,
        timestamp,
    } = props

    return (
        <Stack spacing={1}>
            <TextField autoFocus label="Date and time" onChange={onTimestampChange} required size="small" type="datetime-local" value={timestamp} />
            <Button onClick={onRegister} size="small" variant="contained">
                Schedule action
            </Button>
            {message ? (
                <Typography color="text.secondary" role="status" variant="caption">
                    {message}
                </Typography>
            ) : null}
        </Stack>
    )
}

const { pendingScheduleIds } = require('./schedule_store');

const MAX_TIMER_DELAY_MS = 2147483647;

function cancelScheduleTimer(timers, scheduleId, clearTimeout) {
    const timer = timers.get(scheduleId);
    if (timer) clearTimeout(timer);
    timers.delete(scheduleId);
}

function clearScheduleTimers(timers, clearTimeout) {
    for (const timer of timers.values()) clearTimeout(timer);
    timers.clear();
}

function createScheduleTimerCallback(schedule, fireAt, dependencies) {
    return () => {
        if (fireAt > dependencies.now()) {
            registerAtScheduleTimer(schedule, new Date(fireAt).toISOString(), dependencies);
            return;
        }

        void dependencies.fireSchedule(schedule.id);
    };
}

function registerAtScheduleTimer(schedule, timestamp, dependencies) {
    const fireAt = Date.parse(timestamp);
    if (Number.isNaN(fireAt)) {
        void dependencies.failSchedule(schedule, `Invalid action schedule timestamp: ${timestamp}`);
        return;
    }

    const delay = Math.min(Math.max(fireAt - dependencies.now(), 0), MAX_TIMER_DELAY_MS);
    const callback = createScheduleTimerCallback(schedule, fireAt, dependencies);
    const timer = dependencies.setTimeout(callback, delay);
    dependencies.timers.set(schedule.id, timer);
}

function registerPendingScheduleTimer(schedule, dependencies) {
    if (schedule.trigger.type !== 'at') throw new Error(`Unsupported action schedule trigger: ${schedule.trigger.type}`);

    registerAtScheduleTimer(schedule, schedule.trigger.timestamp, dependencies);
}

function reconcileScheduleTimers(schedules, dependencies) {
    const activeScheduleIds = pendingScheduleIds(schedules);

    for (const [scheduleId, timer] of dependencies.timers.entries()) {
        if (activeScheduleIds.has(scheduleId)) continue;
        dependencies.clearTimeout(timer);
        dependencies.timers.delete(scheduleId);
    }

    for (const schedule of schedules) {
        if (schedule.status !== 'pending') continue;
        if (dependencies.timers.has(schedule.id)) continue;
        registerPendingScheduleTimer(schedule, dependencies);
    }
}

module.exports = {
    cancelScheduleTimer,
    clearScheduleTimers,
    reconcileScheduleTimers,
    registerPendingScheduleTimer,
};

