}

export function cardAgentTokenUsage(source: AgentConversation[] | ProjectSnapshot['activeCards'][number]): AgentTokenUsage {
    const conversations = Array.isArray(source) ? source : source.agentConversations

    return sumAgentTokenUsage(conversations.map(({ usage }) => usage))
}

/** Aggregate loaded conversations belonging to one action on one card. */
export function actionCardAgentTokenUsage(conversations: AgentConversation[], actionId: string, cardInternalId: string): AgentTokenUsage {
    const matchingUsage = conversations
        .filter((conversation) => conversation.actionId === actionId && conversation.cardInternalId === cardInternalId)
        .map(({ usage }) => usage)

    return sumAgentTokenUsage(matchingUsage)
}

/** Sum completed provider patches in one canonical conversation. */
export function conversationFileChangeUsage(conversation: AgentConversation | null): AgentFileChangeUsage | null {
    if (!conversation) return null
    let countedEvents = 0
    let deletions = 0
    let insertions = 0
    for (const entry of conversation.entries) {
        if (entry.kind !== 'event' || entry.type !== 'fileChange' || entry.status !== 'completed') continue
        const { deletions: eventDeletions, insertions: eventInsertions } = entry
        if (typeof eventDeletions !== 'number' || !Number.isSafeInteger(eventDeletions) || eventDeletions < 0) continue
        if (typeof eventInsertions !== 'number' || !Number.isSafeInteger(eventInsertions) || eventInsertions < 0) continue

        countedEvents += 1
        deletions += eventDeletions
        insertions += eventInsertions
    }

    return countedEvents > 0 ? { deletions, insertions } : null
}

function isInsideFolder(cardPath: string, folder: string) {
    const normalizedFolder = folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')

    return normalizedCardPath.startsWith(`${normalizedFolder}/`)
}

/** Use persisted project/release totals while deriving current and archived detail from loaded activity. */
export function projectAgentTokenUsage(
    snapshot: ProjectSnapshot | null,
    archivedFolder: string,
    summary: AgentTokenUsageSummary,
): ProjectAgentUsage {
    const activeCards = snapshot?.activeCards ?? []
    const backgroundCards = snapshot?.backgroundCards ?? []
    const currentUsage = sumAgentTokenUsage(activeCards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)))
    const archivedUsage = sumAgentTokenUsage(
        backgroundCards
            .filter((card) => isInsideFolder(card.path, archivedFolder))
            .map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)),
    )
    const releases = Object.entries(summary.releases)
        .map(([name, usage]) => ({ name, usage }))
        .sort((left, right) => left.name.localeCompare(right.name))

    return {
        archived: { name: 'Archived', usage: archivedUsage },
        current: { name: 'Current', usage: currentUsage },
        project: summary.projectUsage,
        releases,
    }
}

const RATE_LIMIT_EVENT = 'rateLimits';
const WINDOW_IDS = new Set(['five_hour', 'weekly']);

function normalizeWindow(window) {
    if (!window || typeof window !== 'object' || Array.isArray(window)) return null;
    if (!WINDOW_IDS.has(window.id)) return null;
    if (!Number.isInteger(window.usedPercent) || window.usedPercent < 0 || window.usedPercent > 100) return null;
    // Claude omits the reset time for a window it has not started; the percentage is still usable.
    if (window.resetsAt !== null && !Number.isFinite(window.resetsAt)) return null;

    return { id: window.id, resetsAt: window.resetsAt ?? null, usedPercent: window.usedPercent };
}

function normalizeWindows(payload) {
    if (!payload || typeof payload !== 'object' || Array.isArray(payload) || !Array.isArray(payload.windows)) return null;
    const windows = payload.windows.map(normalizeWindow);
    if (windows.some((window) => window === null) || windows.length !== WINDOW_IDS.size) return null;
    if (new Set(windows.map(({ id }) => id)).size !== WINDOW_IDS.size) return null;
    if (!windows.every(({ id }) => WINDOW_IDS.has(id))) return null;

    return windows;
}

function sameWindows(left, right) {
    return left.length === right.length && left.every((window, index) => (
        window.id === right[index].id
        && window.resetsAt === right[index].resetsAt
        && window.usedPercent === right[index].usedPercent
    ));
}

/** Owns latest account-wide Claude rate-limit snapshot in desktop process. */
class ClaudeRuntimeService {
    constructor() {
        this.events = new EventTarget();
        this.snapshot = null;
    }

    getSnapshot() {
        return this.snapshot ? structuredClone(this.snapshot) : null;
    }

    subscribe(listener) {
        const handleRateLimits = (event) => listener(event.detail);
        this.events.addEventListener(RATE_LIMIT_EVENT, handleRateLimits);
        if (this.snapshot) listener(this.getSnapshot());

        return () => this.events.removeEventListener(RATE_LIMIT_EVENT, handleRateLimits);
    }

    publishRateLimits(payload, observedAt) {
        if (!Number.isFinite(observedAt)) throw new Error('Invalid Claude rate-limit observation time');
        if (this.snapshot && observedAt < this.snapshot.observedAt) return false;
        const windows = normalizeWindows(payload);
        if (!windows) return false;
        const changed = !this.snapshot || !this.snapshot.available || !sameWindows(this.snapshot.windows, windows);
        this.snapshot = { available: true, observedAt, windows };
        if (changed) this.notify();

        return true;
    }

    publishUnavailable(observedAt) {
        if (!Number.isFinite(observedAt)) throw new Error('Invalid Claude rate-limit observation time');
        if (this.snapshot && observedAt < this.snapshot.observedAt) return false;
        const changed = !this.snapshot || this.snapshot.available;
        this.snapshot = { available: false, observedAt, windows: [] };
        if (changed) this.notify();

        return true;
    }

    notify() {
        this.events.dispatchEvent(new CustomEvent(RATE_LIMIT_EVENT, { detail: this.getSnapshot() }));
    }
}

module.exports = { ClaudeRuntimeService };

