const UNIX_MILLISECONDS_THRESHOLD = 1_000_000_000_000

export interface ActionScheduleAccountTracker {
    agent: 'claude' | 'codex'
    agentLabel: string
    expectedResetAt: string | null
    label: string
    limitId: string
    usedPercent: number
    windowId: string
}

